43	                "GLM5.2 CuTe DSL fp8 GEMM AOT loaded; wide-route buckets 16-96 dispatch to tcgen05"
44	            );
45	        } else {
46	            log::warn!("GLM5.2 CuTe DSL fp8 GEMM module load failed (rc={rc}); staying on CUTLASS");
47	        }
48	    });
