226	/// Minimum workspace for the grouped GEMM: per-group pointer/stride/layout
227	/// arrays plus the CUTLASS grouped-kernel workspace.
228	pub const GLM52_FP8_GROUPED_GEMM_WORKSPACE_BYTES: usize = 16 << 20;
229	
230	/// Grouped fp8 blockwise GEMM over `num_groups` expert slices (FlashInfer
231	/// `CutlassFP8GroupwiseScaledGroupGEMMSM100`, compiled from source — no
232	/// cubins): group `g` computes `out[m_indptr[g]..m_indptr[g+1], :n] =
233	/// deq(act rows) @ deq(weight[g])^T`. Activation rows are pre-gathered in
234	/// `m_indptr` order; `weight` is the routed slice bank base `[num_groups, n,
235	/// k]` fp8 with `weight_scale` `[num_groups, n/128, k/128]` f32 (checkpoint
236	/// layout as-is, same contract as the dense launch above). `m_indptr` is
237	/// device-resident — per-group row counts never touch the host.
238	#[allow(clippy::too_many_arguments)]
239	pub fn glm52_fp8_grouped_gemm_sm100_launch(
240	    ctx: &DeviceContext,
241	    max_m: usize,
242	    n: usize,
243	    k: usize,
244	    num_groups: usize,
245	    activation: &CudaSlice<u8>,
246	    activation_scale: &CudaSlice<f32>,
247	    weight: &CudaSlice<u8>,
248	    weight_scale: &CudaSlice<f32>,
249	    m_indptr: &CudaSlice<i32>,
250	    output: &mut CudaSlice<bf16>,
251	    workspace: &mut CudaSlice<u8>,
252	) -> Result<()> {
253	    ensure!(
254	        max_m > 0 && n > 0 && n.is_multiple_of(64) && k.is_multiple_of(128) && num_groups > 0,
255	        "GLM5.2 grouped FP8 GEMM shape [{max_m}, {n}, {k}] x {num_groups} is invalid"
256	    );
257	    ensure!(
258	        activation.len() >= max_m * k
259	            && activation_scale.len() >= max_m * k.div_ceil(128)
260	            && weight.len() >= num_groups * n * k
261	            && weight_scale.len() >= num_groups * n.div_ceil(128) * k.div_ceil(128)
262	            && m_indptr.len() > num_groups
263	            && output.len() >= max_m * n
264	            && workspace.len() >= GLM52_FP8_GROUPED_GEMM_WORKSPACE_BYTES,
265	        "GLM5.2 grouped FP8 GEMM buffers are too small for [{max_m}, {n}, {k}] x {num_groups}"
266	    );
267	    let (activation_ptr, _activation_guard) = activation.device_ptr(&ctx.stream);
268	    let (activation_scale_ptr, _activation_scale_guard) = activation_scale.device_ptr(&ctx.stream);
269	    let (weight_ptr, _weight_guard) = weight.device_ptr(&ctx.stream);
270	    let (weight_scale_ptr, _weight_scale_guard) = weight_scale.device_ptr(&ctx.stream);
271	    let (indptr_ptr, _indptr_guard) = m_indptr.device_ptr(&ctx.stream);
272	    let (output_ptr, _output_guard) = output.device_ptr_mut(&ctx.stream);
273	    let workspace_bytes = workspace.len();
274	    let (workspace_ptr, _workspace_guard) = workspace.device_ptr_mut(&ctx.stream);
275	    let result = unsafe {
276	        ffi::glm52_fp8_grouped_gemm_sm100_cuda(
277	            activation_ptr as *const u8,
278	            activation_scale_ptr as *const f32,
279	            weight_ptr as *const u8,
280	            weight_scale_ptr as *const f32,
281	            output_ptr as *mut ffi::Half,
282	            indptr_ptr as *const i32,
283	            max_m as i32,
284	            n as i32,
285	            k as i32,
286	            num_groups as i32,
287	            workspace_ptr as *mut u8,
288	            workspace_bytes,
289	            ctx.stream.cu_stream(),
290	        )
291	    };
292	    result
293	        .result()
294	        .map_err(|err| anyhow!("GLM5.2 grouped FP8 GEMM launch failed: {err}"))
295	}
