1	use std::sync::Once;
2	use std::sync::atomic::AtomicBool;
3	use std::sync::atomic::Ordering;
4	
5	use anyhow::Result;
6	use anyhow::anyhow;
7	use anyhow::ensure;
8	use cudarc::driver::CudaSlice;
9	use cudarc::driver::DevicePtr;
10	use cudarc::driver::DevicePtrMut;
11	use half::bf16;
12	
13	use crate::ffi;
14	use crate::tensor::DeviceContext;
15	
16	static DSL_GEMM_INIT: Once = Once::new();
17	static DSL_GEMM_READY: AtomicBool = AtomicBool::new(false);
18	
19	/// Whether the CuTe DSL AOT table is loaded and dispatching (after
20	/// [`glm52_fp8_dsl_preload`]). False on stub builds and under the kill switch.
21	pub fn glm52_fp8_dsl_gemm_ready() -> bool {
22	    DSL_GEMM_READY.load(Ordering::Acquire)
23	}
24	
25	/// Load the CuTe DSL AOT GEMM modules (embedded cubins) onto every device.
26	/// Must run before any decode-bucket CUDA-graph capture — library load is
27	/// illegal mid-capture; the launch entries themselves are capture-safe.
28	/// No-op on stub builds (no PEGAINFER_CUTEDSL_PYTHON at compile time) and
29	/// under the `GLM52_FP8_DSL=0` kill switch.
30	pub fn glm52_fp8_dsl_preload() {
31	    DSL_GEMM_INIT.call_once(|| {
32	        if std::env::var("GLM52_FP8_DSL").is_ok_and(|v| v == "0") {
33	            log::info!("GLM5.2 CuTe DSL fp8 GEMM disabled by GLM52_FP8_DSL=0");
34	            return;
35	        }
36	        if unsafe { ffi::glm52_fp8_dsl_gemm_supported_cuda(64, 16384, 2048) } == 0 {
37	            return;
38	        }
39	        let rc = unsafe { ffi::glm52_fp8_dsl_gemm_load_cuda() };
40	        if rc == 0 {
41	            DSL_GEMM_READY.store(true, Ordering::Release);
42	            log::info!(
43	                "GLM5.2 CuTe DSL fp8 GEMM AOT loaded; wide-route buckets 16-96 dispatch to tcgen05"
44	            );
45	        } else {
46	            log::warn!("GLM5.2 CuTe DSL fp8 GEMM module load failed (rc={rc}); staying on CUTLASS");
47	        }
48	    });
49	}
50	
51	pub fn glm52_fp8_groupwise_gemm_sm100_launch(
52	    ctx: &DeviceContext,
53	    m: usize,
54	    n: usize,
55	    k: usize,
56	    activation: &CudaSlice<u8>,
57	    activation_scale: &CudaSlice<f32>,
58	    weight: &CudaSlice<u8>,
59	    weight_scale: &CudaSlice<u8>,
60	    output: &mut CudaSlice<bf16>,
61	    workspace: &mut CudaSlice<u8>,
62	) -> Result<()> {
63	    glm52_fp8_groupwise_gemm_sm100_offset_launch(
64	        ctx,
65	        m,
66	        n,
67	        k,
68	        activation,
69	        activation_scale,
70	        weight,
71	        0,
72	        weight_scale,
73	        0,
74	        output,
75	        workspace,
76	    )
77	}
78	
79	#[allow(clippy::cast_ptr_alignment, clippy::too_many_arguments)]
80	pub fn glm52_fp8_groupwise_gemm_sm100_offset_launch(
81	    ctx: &DeviceContext,
82	    m: usize,
83	    n: usize,
84	    k: usize,
85	    activation: &CudaSlice<u8>,
86	    activation_scale: &CudaSlice<f32>,
87	    weight: &CudaSlice<u8>,
88	    weight_offset: usize,
89	    weight_scale: &CudaSlice<u8>,
90	    weight_scale_offset: usize,
91	    output: &mut CudaSlice<bf16>,
92	    workspace: &mut CudaSlice<u8>,
93	) -> Result<()> {
94	    ensure!(
95	        m > 0 && m.is_multiple_of(4) && n > 0 && k.is_multiple_of(128),
96	        "GLM5.2 FP8 GEMM shape [{m}, {n}, {k}] requires m%4=0, n>0, and k%128=0"
97	    );
98	    ensure!(
99	        weight_scale_offset.is_multiple_of(align_of::<f32>()),
100	        "GLM5.2 FP8 weight scale offset {weight_scale_offset} is not f32-aligned"
101	    );
102	    ensure!(
103	        activation.len() >= m * k
104	            && activation_scale.len() >= m * k.div_ceil(128)
105	            && weight.len() >= weight_offset + n * k
106	            && weight_scale.len()
107	                >= weight_scale_offset + n.div_ceil(128) * k.div_ceil(128) * size_of::<f32>()
108	            && output.len() >= m * n
109	            && !workspace.is_empty(),
110	        "GLM5.2 FP8 GEMM buffers are too small for [{m}, {n}, {k}]"
111	    );
112	    let (activation_ptr, _activation_guard) = activation.device_ptr(&ctx.stream);
113	    let (activation_scale_ptr, _activation_scale_guard) = activation_scale.device_ptr(&ctx.stream);
114	    let (weight_ptr, _weight_guard) = weight.device_ptr(&ctx.stream);
115	    let (weight_scale_ptr, _weight_scale_guard) = weight_scale.device_ptr(&ctx.stream);
116	    let (output_ptr, _output_guard) = output.device_ptr_mut(&ctx.stream);
117	    let workspace_bytes = workspace.len();
118	    let (workspace_ptr, _workspace_guard) = workspace.device_ptr_mut(&ctx.stream);
119	    // Exact-(m, n, k) table dispatch to the CuTe DSL tcgen05 AOT twin: only
120	    // the four wide-route projection shapes at decode buckets 16-96 hit it.
121	    // The branch is deterministic per bucket, so graph capture and replay
122	    // agree.
123	    if weight_offset == 0
124	        && weight_scale_offset == 0
125	        && DSL_GEMM_READY.load(Ordering::Acquire)
126	        && unsafe { ffi::glm52_fp8_dsl_gemm_supported_cuda(m as i32, n as i32, k as i32) } != 0
127	    {
128	        let rc = unsafe {
129	            ffi::glm52_fp8_dsl_gemm_cuda(
130	                activation_ptr as *const u8,
131	                activation_scale_ptr as *const f32,
132	                weight_ptr as *const u8,
133	                weight_scale_ptr as *const u8 as *const f32,
134	                output_ptr as *mut ffi::Half,
135	                workspace_ptr as *mut u8,
136	                workspace_bytes,
137	                m as i32,
138	                n as i32,
139	                k as i32,
140	                ctx.stream.cu_stream(),
141	            )
142	        };
143	        ensure!(
144	            rc == 0,
145	            "GLM5.2 CuTe DSL fp8 GEMM failed (rc={rc}) for [{m}, {n}, {k}]"
146	        );
147	        return Ok(());
148	    }
149	    let result = unsafe {
150	        ffi::glm52_fp8_groupwise_gemm_sm100_cuda(
151	            activation_ptr as *const u8,
152	            activation_scale_ptr as *const f32,
153	            (weight_ptr as *const u8).add(weight_offset),
154	            (weight_scale_ptr as *const u8)
155	                .add(weight_scale_offset)
156	                .cast::<f32>(),
157	            output_ptr as *mut ffi::Half,
158	            workspace_ptr as *mut u8,
159	            workspace_bytes,
160	            m as i32,
161	            n as i32,
162	            k as i32,
163	            ctx.stream.cu_stream(),
164	        )
165	    };
166	    result
167	        .result()
168	        .map_err(|err| anyhow!("GLM5.2 FP8 groupwise GEMM launch failed: {err}"))
169	}
170	
171	#[allow(clippy::too_many_arguments)]
172	pub fn glm52_fp8_groupwise_gemm_sm100_bank_launch(
173	    ctx: &DeviceContext,
174	    m: usize,
175	    n: usize,
176	    k: usize,
177	    activation: &CudaSlice<u8>,
178	    activation_scale: &CudaSlice<f32>,
179	    weight: &CudaSlice<u8>,
180	    weight_offset: usize,
181	    weight_scale: &CudaSlice<f32>,
182	    weight_scale_offset: usize,
183	    output: &mut CudaSlice<bf16>,
184	    workspace: &mut CudaSlice<u8>,
185	) -> Result<()> {
186	    ensure!(
187	        m > 0 && m.is_multiple_of(4) && n > 0 && k.is_multiple_of(128),
188	        "GLM5.2 bank FP8 GEMM shape [{m}, {n}, {k}] is invalid"
189	    );
190	    ensure!(
191	        activation.len() >= m * k
192	            && activation_scale.len() >= m * k.div_ceil(128)
193	            && weight.len() >= weight_offset + n * k
194	            && weight_scale.len() >= weight_scale_offset + n.div_ceil(128) * k.div_ceil(128)
195	            && output.len() >= m * n
196	            && !workspace.is_empty(),
197	        "GLM5.2 bank FP8 GEMM buffers are too small"
198	    );
199	    let (activation_ptr, _activation_guard) = activation.device_ptr(&ctx.stream);
200	    let (activation_scale_ptr, _activation_scale_guard) = activation_scale.device_ptr(&ctx.stream);
201	    let (weight_ptr, _weight_guard) = weight.device_ptr(&ctx.stream);
202	    let (weight_scale_ptr, _weight_scale_guard) = weight_scale.device_ptr(&ctx.stream);
203	    let (output_ptr, _output_guard) = output.device_ptr_mut(&ctx.stream);
204	    let workspace_bytes = workspace.len();
205	    let (workspace_ptr, _workspace_guard) = workspace.device_ptr_mut(&ctx.stream);
206	    let result = unsafe {
207	        ffi::glm52_fp8_groupwise_gemm_sm100_cuda(
208	            activation_ptr as *const u8,
209	            activation_scale_ptr as *const f32,
210	            (weight_ptr as *const u8).add(weight_offset),
211	            (weight_scale_ptr as *const f32).add(weight_scale_offset),
212	            output_ptr as *mut ffi::Half,
213	            workspace_ptr as *mut u8,
214	            workspace_bytes,
215	            m as i32,
216	            n as i32,
217	            k as i32,
218	            ctx.stream.cu_stream(),
219	        )
220	    };
221	    result
222	        .result()
223	        .map_err(|err| anyhow!("GLM5.2 bank FP8 GEMM launch failed: {err}"))
224	}
225	
226	/// Minimum workspace for the grouped GEMM: per-group pointer/stride/layout
227	/// arrays plus the CUTLASS grouped-kernel workspace.
228	pub const GLM52_FP8_GROUPED_GEMM_WORKSPACE_BYTES: usize = 16 << 20;
229	
230	/// Grouped fp8 blockwise GEMM over `num_groups` expert slices (FlashInfer
231	/// `CutlassFP8GroupwiseScaledGroupGEMMSM100`, compiled from source — no
232	/// cubins): group `g` computes `out[m_indptr[g]..m_indptr[g+1], :n] =
233	/// deq(act rows) @ deq(weight[g])^T`. Activation rows are pre-gathered in
234	/// `m_indptr` order; `weight` is the routed slice bank base `[num_groups, n,
235	/// k]` fp8 with `weight_scale` `[num_groups, n/128, k/128]` f32 (checkpoint
236	/// layout as-is, same contract as the dense launch above). `m_indptr` is
237	/// device-resident — per-group row counts never touch the host.
238	#[allow(clippy::too_many_arguments)]
239	pub fn glm52_fp8_grouped_gemm_sm100_launch(
240	    ctx: &DeviceContext,
241	    max_m: usize,
242	    n: usize,
243	    k: usize,
244	    num_groups: usize,
245	    activation: &CudaSlice<u8>,
246	    activation_scale: &CudaSlice<f32>,
247	    weight: &CudaSlice<u8>,
248	    weight_scale: &CudaSlice<f32>,
249	    m_indptr: &CudaSlice<i32>,
250	    output: &mut CudaSlice<bf16>,
251	    workspace: &mut CudaSlice<u8>,
252	) -> Result<()> {
253	    ensure!(
254	        max_m > 0 && n > 0 && n.is_multiple_of(64) && k.is_multiple_of(128) && num_groups > 0,
255	        "GLM5.2 grouped FP8 GEMM shape [{max_m}, {n}, {k}] x {num_groups} is invalid"
256	    );
257	    ensure!(
258	        activation.len() >= max_m * k
259	            && activation_scale.len() >= max_m * k.div_ceil(128)
260	            && weight.len() >= num_groups * n * k
261	            && weight_scale.len() >= num_groups * n.div_ceil(128) * k.div_ceil(128)
262	            && m_indptr.len() > num_groups
263	            && output.len() >= max_m * n
264	            && workspace.len() >= GLM52_FP8_GROUPED_GEMM_WORKSPACE_BYTES,
265	        "GLM5.2 grouped FP8 GEMM buffers are too small for [{max_m}, {n}, {k}] x {num_groups}"
266	    );
267	    let (activation_ptr, _activation_guard) = activation.device_ptr(&ctx.stream);
268	    let (activation_scale_ptr, _activation_scale_guard) = activation_scale.device_ptr(&ctx.stream);
269	    let (weight_ptr, _weight_guard) = weight.device_ptr(&ctx.stream);
270	    let (weight_scale_ptr, _weight_scale_guard) = weight_scale.device_ptr(&ctx.stream);
271	    let (indptr_ptr, _indptr_guard) = m_indptr.device_ptr(&ctx.stream);
272	    let (output_ptr, _output_guard) = output.device_ptr_mut(&ctx.stream);
273	    let workspace_bytes = workspace.len();
274	    let (workspace_ptr, _workspace_guard) = workspace.device_ptr_mut(&ctx.stream);
275	    let result = unsafe {
276	        ffi::glm52_fp8_grouped_gemm_sm100_cuda(
277	            activation_ptr as *const u8,
278	            activation_scale_ptr as *const f32,
279	            weight_ptr as *const u8,
280	            weight_scale_ptr as *const f32,
281	            output_ptr as *mut ffi::Half,
282	            indptr_ptr as *const i32,
283	            max_m as i32,
284	            n as i32,
285	            k as i32,
286	            num_groups as i32,
287	            workspace_ptr as *mut u8,
288	            workspace_bytes,
289	            ctx.stream.cu_stream(),
290	        )
291	    };
292	    result
293	        .result()
294	        .map_err(|err| anyhow!("GLM5.2 grouped FP8 GEMM launch failed: {err}"))
295	}
