297	#[cfg(test)]
298	mod tests {
299	    use super::*;
300	
301	    #[test]
302	    #[ignore = "requires an SM100/103 CUDA device"]
303	    fn fp8_groupwise_respects_row_major_weight() -> Result<()> {
304	        const M: usize = 4;
305	        const N: usize = 128;
306	        const K: usize = 128;
307	        const VALUES: [(u8, f32); 5] = [
308	            (0xc0, -2.0),
309	            (0xb8, -1.0),
310	            (0x00, 0.0),
311	            (0x38, 1.0),
312	            (0x40, 2.0),
313	        ];
314	
315	        let ctx = DeviceContext::new()?;
316	        let mut activation_host = vec![0u8; M * K];
317	        for row in 0..M {
318	            for col in 0..K {
319	                activation_host[row * K + col] = VALUES[(row * 3 + col) % VALUES.len()].0;
320	            }
321	        }
322	        let mut weight_host = vec![0u8; N * K];
323	        for row in 0..N {
324	            weight_host[row * K + (row * 7 + 3) % K] =
325	                if row.is_multiple_of(2) { 0x38 } else { 0xb8 };
326	        }
327	        let activation = ctx.stream.clone_htod(&activation_host)?;
328	        let activation_scale = ctx.stream.clone_htod(&vec![1.0f32; M])?;
329	        let weight = ctx.stream.clone_htod(&weight_host)?;
330	        let weight_scale = ctx.stream.clone_htod(&1.0f32.to_ne_bytes())?;
331	        let mut output = ctx.stream.alloc_zeros::<bf16>(M * N)?;
332	        let mut workspace = ctx.stream.alloc_zeros::<u8>(32 << 20)?;
333	
334	        glm52_fp8_groupwise_gemm_sm100_launch(
335	            &ctx,
336	            M,
337	            N,
338	            K,
339	            &activation,
340	            &activation_scale,
341	            &weight,
342	            &weight_scale,
343	            &mut output,
344	            &mut workspace,
345	        )?;
346	        let output = ctx.stream.clone_dtoh(&output)?;
347	        for row in 0..M {
348	            for col in 0..N {
349	                let source_col = (col * 7 + 3) % K;
350	                let source = VALUES[(row * 3 + source_col) % VALUES.len()].1;
351	                let want = if col.is_multiple_of(2) {
352	                    source
353	                } else {
354	                    -source
355	                };
356	                ensure!(
357	                    output[row * N + col].to_f32() == want,
358	                    "output[{row}, {col}]={} != {want}",
359	                    output[row * N + col].to_f32()
360	                );
361	            }
362	        }
363	        Ok(())
364	    }
365	
366	    /// Grouped GEMM vs an exact hand-computed reference: 4 expert groups
367	    /// (one empty), one-hot ±1 weights, unit scales — every output element
368	    /// is an exact copy/negation of one activation value.
369	    #[test]
370	    #[ignore = "requires an SM100/103 CUDA device"]
371	    fn fp8_grouped_gemm_matches_reference() -> Result<()> {
372	        const GROUPS: usize = 4;
373	        const N: usize = 128;
374	        const K: usize = 256;
375	        const TOTAL_M: usize = 16;
376	        const INDPTR: [i32; GROUPS + 1] = [0, 3, 3, 8, 16];
377	        const VALUES: [(u8, f32); 5] = [
378	            (0xc0, -2.0),
379	            (0xb8, -1.0),
380	            (0x00, 0.0),
381	            (0x38, 1.0),
382	            (0x40, 2.0),
383	        ];
384	
385	        let ctx = DeviceContext::new()?;
386	        let mut activation_host = vec![0u8; TOTAL_M * K];
387	        for row in 0..TOTAL_M {
388	            for col in 0..K {
389	                activation_host[row * K + col] = VALUES[(row * 3 + col) % VALUES.len()].0;
390	            }
391	        }
392	        let mut weight_host = vec![0u8; GROUPS * N * K];
393	        for group in 0..GROUPS {
394	            for row in 0..N {
395	                weight_host[group * N * K + row * K + (row * 7 + group * 3 + 3) % K] =
396	                    if row.is_multiple_of(2) { 0x38 } else { 0xb8 };
397	            }
398	        }
399	        let activation = ctx.stream.clone_htod(&activation_host)?;
400	        let activation_scale = ctx.stream.clone_htod(&vec![1.0f32; TOTAL_M * (K / 128)])?;
401	        let weight = ctx.stream.clone_htod(&weight_host)?;
402	        let weight_scale = ctx
403	            .stream
404	            .clone_htod(&vec![1.0f32; GROUPS * (N / 128) * (K / 128)])?;
405	        let m_indptr = ctx.stream.clone_htod(&INDPTR)?;
406	        let mut output = ctx.stream.alloc_zeros::<bf16>(TOTAL_M * N)?;
407	        let mut workspace = ctx
408	            .stream
409	            .alloc_zeros::<u8>(GLM52_FP8_GROUPED_GEMM_WORKSPACE_BYTES)?;
410	
411	        glm52_fp8_grouped_gemm_sm100_launch(
412	            &ctx,
413	            TOTAL_M,
414	            N,
415	            K,
416	            GROUPS,
417	            &activation,
418	            &activation_scale,
419	            &weight,
420	            &weight_scale,
421	            &m_indptr,
422	            &mut output,
423	            &mut workspace,
424	        )?;
425	        let output = ctx.stream.clone_dtoh(&output)?;
426	        for group in 0..GROUPS {
427	            for row in INDPTR[group] as usize..INDPTR[group + 1] as usize {
428	                for col in 0..N {
429	                    let source_col = (col * 7 + group * 3 + 3) % K;
430	                    let source = VALUES[(row * 3 + source_col) % VALUES.len()].1;
431	                    let want = if col.is_multiple_of(2) {
432	                        source
433	                    } else {
434	                        -source
435	                    };
436	                    ensure!(
437	                        output[row * N + col].to_f32() == want,
438	                        "group {group} output[{row}, {col}]={} != {want}",
439	                        output[row * N + col].to_f32()
440	                    );
441	                }
442	            }
443	        }
444	        Ok(())
445	    }
