456	        let weight = ctx.stream.clone_htod(&vec![0x38u8; N * K])?;
457	        let scale_bytes: Vec<u8> = vec![1.0f32; N.div_ceil(128)]
458	            .into_iter()
459	            .flat_map(f32::to_ne_bytes)
460	            .collect();
461	        let weight_scale = ctx.stream.clone_htod(&scale_bytes)?;
462	        let mut output = ctx.stream.alloc_zeros::<bf16>(M * N)?;
463	        let mut workspace = ctx.stream.alloc_zeros::<u8>(32 << 20)?;
464	        glm52_fp8_groupwise_gemm_sm100_launch(
465	            &ctx,
466	            M,
467	            N,
468	            K,
469	            &activation,
470	            &activation_scale,
471	            &weight,
472	            &weight_scale,
473	            &mut output,
474	            &mut workspace,
475	        )?;
476	        let output = ctx.stream.clone_dtoh(&output)?;
477	        ensure!(
478	            output.iter().all(|value| value.to_f32() == K as f32),
479	            "576-column tail GEMM produced an unexpected value"
480	        );
481	        Ok(())
