1	//! GLM5.2 dense-MLP decode forward for bs=1 (layers 0..first_k_dense_replace).
2	//!
3	//! The dense layers replace the MoE block with a plain fp8 SwiGLU MLP
4	//! `down(silu(gate(x)) * up(x))` -- the same shape as the MoE shared expert, only
5	//! the intermediate is wider (12288 vs 2048). It reuses the shared `fp8_mlp`
6	//! helper, so this module is just the weight bundle + a thin forward.
7	
8	use anyhow::Result;
9	use cudarc::driver::CudaSlice;
10	use half::bf16;
11	use pegainfer_kernels::ops::glm52_silu_and_mul_bf16_launch;
12	use pegainfer_kernels::tensor::DeviceContext;
13	
14	use crate::config::GLM52_HIDDEN;
15	use crate::fp8::Glm52Fp8GemmScratch;
16	use crate::fp8::Glm52MlpScratch;
17	#[cfg(test)]
18	use crate::fp8::Glm52ProjBytes;
19	use crate::fp8::ProjWeight;
20	use crate::fp8::fp8_linear_large_m_into;
21	use crate::fp8::fp8_mlp_into;
22	use crate::fp8::pack_proj_pair;
23	
24	const HIDDEN: usize = GLM52_HIDDEN;
25	const INTERMEDIATE: usize = crate::config::GLM52_DENSE_INTERMEDIATE;
26	
27	/// The fp8 projections of one dense MLP layer, resident on device. gate|up
28	/// are packed into one `[2*INTERMEDIATE, HIDDEN]` projection at build (one
29	/// GEMV + SwiGLU + one GEMV at decode).
30	pub(crate) struct Glm52DenseMlpWeights {
31	    gate_up: ProjWeight, // fp8 [2*INTERMEDIATE, HIDDEN] (gate | up)
32	    down: ProjWeight,    // fp8 [HIDDEN, INTERMEDIATE]
33	}
34	
35	impl Glm52DenseMlpWeights {
36	    /// Upload the dense MLP projections, validating every extent against the
37	    /// GLM5.2 dense-layer architecture (crash-early on a packaging drift).
38	    #[cfg(test)]
39	    pub(crate) fn from_host(
40	        ctx: &DeviceContext,
41	        gate: &Glm52ProjBytes<'_>,
42	        up: &Glm52ProjBytes<'_>,
43	        down: &Glm52ProjBytes<'_>,
44	    ) -> Result<Self> {
45	        let shape = |label: &str, p: &Glm52ProjBytes<'_>, n: usize, k: usize| -> Result<()> {
46	            anyhow::ensure!(
47	                p.n == n && p.k == k,
48	                "GLM5.2 dense MLP {label} shape [{},{}] != [{n},{k}]",
49	                p.n,
50	                p.k
51	            );
52	            Ok(())
53	        };
54	        shape("gate_proj", gate, INTERMEDIATE, HIDDEN)?;
55	        shape("up_proj", up, INTERMEDIATE, HIDDEN)?;
56	        shape("down_proj", down, HIDDEN, INTERMEDIATE)?;
57	        Ok(Self {
58	            gate_up: pack_proj_pair(
59	                ctx,
60	                &ProjWeight::upload(ctx, gate)?,
61	                &ProjWeight::upload(ctx, up)?,
62	            )?,
63	            down: ProjWeight::upload(ctx, down)?,
64	        })
65	    }
66	
67	    /// Build from already-resident projections (the production loader path).
68	    pub(crate) fn from_device(
69	        ctx: &DeviceContext,
70	        gate: &ProjWeight,
71	        up: &ProjWeight,
72	        down: ProjWeight,
73	    ) -> Result<Self> {
74	        let shape = |label: &str, p: &ProjWeight, n: usize, k: usize| -> Result<()> {
75	            anyhow::ensure!(
76	                p.n == n && p.k == k,
77	                "GLM5.2 dense MLP {label} shape [{},{}] != [{n},{k}]",
78	                p.n,
79	                p.k
80	            );
81	            Ok(())
82	        };
83	        shape("gate_proj", gate, INTERMEDIATE, HIDDEN)?;
84	        shape("up_proj", up, INTERMEDIATE, HIDDEN)?;
85	        shape("down_proj", &down, HIDDEN, INTERMEDIATE)?;
86	        Ok(Self {
87	            gate_up: pack_proj_pair(ctx, gate, up)?,
88	            down,
89	        })
90	    }
91	}
92	
93	/// Dense MLP contribution for a single token into a pre-allocated output.
94	/// `normed_hidden` is the post-attention-layernorm hidden `[HIDDEN]`; `out`
95	/// gets the MLP output `[HIDDEN]` (the caller adds it to the post-attention
96	/// residual). `mlp` must be sized for the dense intermediate (12288).
97	pub(crate) fn glm52_dense_mlp_forward_into(
98	    ctx: &DeviceContext,
99	    weights: &Glm52DenseMlpWeights,
100	    normed_hidden: &CudaSlice<bf16>,
101	    mlp: &mut Glm52MlpScratch,
102	    out: &mut CudaSlice<bf16>,
103	) -> Result<()> {
104	    fp8_mlp_into(
105	        ctx,
106	        &weights.gate_up,
107	        &weights.down,
108	        normed_hidden,
109	        mlp,
110	        out,
111	    )
112	}
113	
114	pub(crate) fn glm52_dense_mlp_prefill_into(
115	    ctx: &DeviceContext,
116	    weights: &Glm52DenseMlpWeights,
117	    rows: usize,
118	    normed_hidden: &impl cudarc::driver::DevicePtr<bf16>,
119	    gemm: &mut Glm52Fp8GemmScratch,
120	    gate_up: &mut CudaSlice<bf16>,
121	    silu: &mut CudaSlice<bf16>,
122	    out: &mut CudaSlice<bf16>,
123	) -> Result<()> {
124	    fp8_linear_large_m_into(ctx, &weights.gate_up, rows, normed_hidden, gemm, gate_up)?;
125	    glm52_silu_and_mul_bf16_launch(ctx, rows, INTERMEDIATE, gate_up, silu)?;
126	    fp8_linear_large_m_into(ctx, &weights.down, rows, silu, gemm, out)
127	}
